#include <array>
#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 256> local{};
        local.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < image.size(); ++i) {
            const int v = image[i];
            // Assuming grayscale values are in [0,255] as stated.
            ++local[static_cast<std::size_t>(v)];
        }

        // Merge thread-local histograms safely into global bins.
        #pragma omp critical
        {
            for (std::size_t k = 0; k < 256; ++k) {
                bins[k] += local[k];
            }
        }
    }
}
